mapper.select:
SELECT ps.style_id, ps.style_name, ps.style_type, ps.style_image, ps.pc_image, ps.start_time, ps.end_time, ps.status, ps.shop_id, ps.add_time, ps.update_time, IFNULL(cnt.product_count, 0) AS product_count FROM product_style ps LEFT JOIN ( SELECT psi.style_id AS style_id, COUNT(DISTINCT p.product_id) AS product_count FROM product_style_item psi INNER JOIN product p ON ( (psi.item_type = 1 AND psi.ref_id = p.product_id) OR (psi.item_type = 2 AND EXISTS ( SELECT 1 FROM product_group pg WHERE pg.product_group_id = psi.ref_id AND JSON_CONTAINS(pg.product_ids, CAST(p.product_id AS JSON)) )) OR (psi.item_type = 3 AND psi.ref_id = p.brand_id) ) WHERE p.is_delete = 0 AND p.product_status = 1 GROUP BY psi.style_id ) cnt ON cnt.style_id = ps.style_id
ps.shop_id = #{shopId} AND ps.is_delete = 0
AND ps.style_type = #{query.styleType}
AND ps.status = #{query.status}
AND ps.style_name LIKE CONCAT('%', #{query.keyword}, '%')
AND ps.start_time > #{now}
AND ps.start_time <= #{now} AND ps.end_time >= #{now}
AND ps.end_time < #{now}
AND ps.start_time >= #{startTime}
AND ps.end_time <= #{endTime}

SELECT psi.style_id AS styleId, COUNT(DISTINCT p.product_id) AS productCount FROM product_style_item psi INNER JOIN product p ON ( (psi.item_type = 1 AND psi.ref_id = p.product_id) OR (psi.item_type = 2 AND EXISTS ( SELECT 1 FROM product_group pg WHERE pg.product_group_id = psi.ref_id AND JSON_CONTAINS(pg.product_ids, CAST(p.product_id AS JSON)) )) OR (psi.item_type = 3 AND psi.ref_id = p.brand_id) ) WHERE psi.style_id IN
#{sid}
AND p.is_delete = 0 AND p.product_status = 1 GROUP BY psi.style_id
